sp_widget.client_script:
api.controller = function () {
  var c = this;
  c.loading = false;

  c.getStatusClass = function (status) {
    if (status === 'verified') return 'label-success';
    if (status === 'rejected') return 'label-danger';
    return 'label-warning';
  };

  c.getStateClass = function () {
    var state = c.data.state;
    if (state === '1') return 'label-info';
    if (state === '2') return 'label-warning';
    if (state === '3') return 'label-primary';
    if (state >= '6') return 'label-success';
    return 'label-default';
  };

  c.getProgressClass = function () {
    var p = c.data.progress;
    if (p >= 80) return 'progress-bar-success';
    if (p >= 40) return 'progress-bar-info';
    return 'progress-bar-warning';
  };
};

sp_widget.css:
/* Progress milestone icons */
.gvft-progress-icon {
  font-size: 20px;
  display: block;
  margin-bottom: 4px;
  color: $text-muted;
}
.gvft-progress-label {
  font-size: $font-size-small;
  margin: 0;
}

sp_widget.script:
(function () {
  data.caseFound = false;
  data.errorMsg = '';
  data.caseNumber = '';
  data.candidateName = '';
  data.candidateEmail = '';
  data.visaCategory = '';
  data.targetCity = '';
  data.state = '';
  data.stateDisplay = '';
  data.feeStatus = '';
  data.feeAmount = '';
  data.createdOn = '';
  data.documents = [];
  data.progress = 0;

  try {
    var caseNum = $sp.getParameter('case');
    if (!caseNum) {
      data.errorMsg = 'No case number provided.';
      return;
    }

    var gr = new GlideRecord('x_2023506_german_1_imm_case');
    gr.addQuery('number', caseNum);
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
      data.caseFound = true;
      data.caseNumber = gr.getValue('number') + '';
      data.caseSysId = gr.getUniqueValue() + '';
      data.candidateName = gr.getValue('u_candidate_name') + '';
      data.candidateEmail = gr.getValue('u_candidate_email') + '';
      data.visaCategory = gr.getDisplayValue('u_visa_category') + '';
      data.targetCity = gr.getValue('u_target_city') + '';
      data.state = gr.getValue('state') + '';
      data.stateDisplay = gr.getDisplayValue('state') + '';
      data.feeStatus = gr.getDisplayValue('u_fee_status') + '';
      data.feeAmount = gr.getValue('u_fee_amount') + '';
      data.createdOn = gr.getDisplayValue('sys_created_on') + '';

      // Query case documents
      var docGr = new GlideRecord('x_2023506_german_1_case_doc');
      docGr.addQuery('u_case', gr.getUniqueValue());
      docGr.setLimit(20);
      docGr.query();

      var verifiedCount = 0;
      var totalDocs = 0;
      while (docGr.next()) {
        totalDocs++;
        var status = docGr.getValue('u_status') + '';
        if (status === 'verified') {
          verifiedCount++;
        }
        data.documents.push({
          sys_id: docGr.getUniqueValue() + '',
          name: docGr.getDisplayValue('u_document_name') + '',
          status: status,
          statusDisplay: docGr.getDisplayValue('u_status') + '',
          reviewNotes: docGr.getValue('u_review_notes') + ''
        });
      }

      // Calculate progress
      var stateVal = parseInt(data.state, 10) || 1;
      var stateProgress = 0;
      if (stateVal === 1) stateProgress = 10;
      else if (stateVal === 2) stateProgress = 40;
      else if (stateVal === 3) stateProgress = 70;
      else if (stateVal >= 6) stateProgress = 100;

      var docProgress = 0;
      if (totalDocs > 0) {
        docProgress = Math.round((verifiedCount / totalDocs) * 50);
      }

      data.progress = Math.min(stateProgress + docProgress, 100);

    } else {
      data.errorMsg = 'Case "' + caseNum + '" not found.';
    }
  } catch (e) {
    gs.error('gvft_status_widget error: ' + e.message);
    data.errorMsg = 'An error occurred loading case details.';
  }
})();
